/*
  HRM Public Directory Frontend
  - ใช้กับหน้า hosting/HRM/personnel-directory.html
  - ดึงข้อมูลบุคลากรจาก Apps Script action: publicList / publicProfile / publicResearch / publicFacultyPractice
  - หน้าแสดงผลแบ่ง 3 กลุ่มหลัก: คณะผู้บริหาร, สายวิชาการ, สายสนับสนุน
  - ฐานข้อมูลเก็บค่าตาม Supabase แต่หน้านี้แปลง/จัดกลุ่มเพื่อให้เหมาะกับการเผยแพร่ภายนอก
*/

// URL ของ Apps Script backend ที่หน้า public HRM เรียกใช้
const API_URL =
  'https://script.google.com/macros/s/AKfycbxe1NQ1APDCMdhrp9f7f_TEGYWS4GkCmLnCS87ARFePJDA9WG-Td_8nPQ9r6SNOgr6wdg/exec';

// State หลักของหน้า: รายชื่อทั้งหมด, รายชื่อที่กำลังแสดง, งานวิจัย, timer สำหรับ debounce render
let publicPeople = [];
let visiblePublicPeople = [];
let publicResearch = [];
let publicFacultyPractice = [];
let publicRenderTimer = 0;

// Cache ฝั่ง browser ช่วยให้เปิดหน้าซ้ำเร็วขึ้น และยังแสดงข้อมูลล่าสุดได้ถ้า backend ล่มชั่วคราว
const PUBLIC_CACHE_KEY = 'hrm_public_people_v5_title_prefix';
const PUBLIC_RESEARCH_CACHE_PREFIX = 'hrm_public_research_person_v2_';
const PUBLIC_CACHE_MAX_AGE = 1000 * 60 * 10;

document.addEventListener('DOMContentLoaded', () => {
  applyPublicAccessControls();
  loadPublicPeople();
});

function getMisUser() {
  try {
    return JSON.parse(localStorage.getItem('mis_user') || 'null');
  } catch (err) {
    return null;
  }
}

function isHrmAdminUser(user) {
  return String(user && (user.hrRole || user.HR_ROLE) || '').trim().toUpperCase() === 'ADMIN';
}

function applyPublicAccessControls() {
  const user = getMisUser();
  const canOpenHrmAdmin = Boolean(user && isHrmAdminUser(user));

  document.querySelectorAll('[data-hr-admin-only]').forEach(el => {
    if (!canOpenHrmAdmin) el.remove();
  });
}

// Wrapper เรียก Apps Script แบบ GET พร้อม action/system ที่ backend ใช้แยกงาน
async function apiGet(action, params = {}) {
  const url = new URL(API_URL);
  url.searchParams.set('action', action);
  url.searchParams.set('system', 'HRM');

  Object.keys(params).forEach(key => {
    url.searchParams.set(key, params[key]);
  });

  const res = await fetch(url.toString());
  return await res.json();
}

// โหลดรายชื่อบุคลากรสำหรับหน้า directory: แสดง cache ก่อน แล้วค่อย refresh จาก backend
async function loadPublicPeople() {
  renderCachedPublicPeople();

  try {
    const res = await apiGet('publicList', { view: 'directory' });
    if (!res.success) throw new Error(res.message || 'โหลดข้อมูลไม่สำเร็จ');

    setPublicPeople(res.data || []);
    cachePublicPeople(res.data || []);

    renderPublicDirectory();
  } catch (err) {
    if (publicPeople.length) {
      document.getElementById('resultSummary').textContent =
        `แสดงข้อมูลล่าสุดที่บันทึกไว้ ${publicPeople.length} คน`;
      return;
    }

    document.getElementById('publicCards').innerHTML =
      `<div class="loading-card">ไม่สามารถโหลดข้อมูลได้: ${escapeHtml(err.message)}</div>`;
    document.getElementById('resultSummary').textContent = 'โหลดข้อมูลไม่สำเร็จ';
  }
}

function setPublicResearch(rows) {
  publicResearch = (rows || []).filter(item => item.PERSON_ID);
}

function setPublicFacultyPractice(rows) {
  publicFacultyPractice = (rows || []).filter(item => item.PERSON_ID);
}

function setPublicPeople(rows) {
  publicPeople = rows
    .filter(isPublicPerson)
    .sort(comparePublicPeople);
  populatePublicDepartmentOptions(publicPeople);
  if (!getActivePublicGroup()) updateGroupChooser('EXECUTIVE');
  renderPublicGroupCounts();
}

// สร้าง dropdown กลุ่มวิชา/หน่วยงานจากข้อมูลจริง และเก็บชื่อจริงไว้ใน data-department-name
function populatePublicDepartmentOptions(rows = []) {
  const select = document.getElementById('publicDepartment');
  if (!select) return;

  const currentValue = select.value;
  const map = new Map();
  rows.forEach(row => {
    const id = normalizeText(row.DEPARTMENT_ID || row.DEPARTMENT || row.DEPARTMENT_NAME);
    const name = normalizeText(row.DEPARTMENT_NAME || row.DEPARTMENT || row.DEPARTMENT_ID);
    if (!id && !name) return;
    map.set(id || name, name || id);
  });

  const options = Array.from(map.entries())
    .sort((a, b) => toDepartmentFilterLabel(a[1]).localeCompare(toDepartmentFilterLabel(b[1]), 'th'));

  select.innerHTML = '<option value="">ทุกกลุ่มวิชา</option>' + options
    .map(([id, name]) => `<option value="${escapeAttr(id)}" data-department-name="${escapeAttr(name)}">${escapeHtml(toDepartmentFilterLabel(name))}</option>`)
    .join('');

  const currentKey = normalizeDepartment(currentValue);
  const matchedOption = Array.from(select.options).find(option =>
    normalizeDepartment(option.value) === currentKey ||
    normalizeDepartment(option.dataset.departmentName) === currentKey ||
    normalizeDepartment(option.textContent) === currentKey
  );
  if (matchedOption) select.value = matchedOption.value;
}

function renderCachedPublicPeople() {
  try {
    const cached = JSON.parse(localStorage.getItem(PUBLIC_CACHE_KEY) || 'null');
    if (!cached || Date.now() - cached.savedAt > PUBLIC_CACHE_MAX_AGE) return;

    setPublicPeople(cached.rows || []);
    renderPublicDirectory();
    document.getElementById('resultSummary').textContent =
      `แสดงข้อมูลล่าสุด ${publicPeople.length} คน`;
  } catch (err) {
    localStorage.removeItem(PUBLIC_CACHE_KEY);
  }
}

function cachePublicPeople(rows) {
  try {
    localStorage.setItem(PUBLIC_CACHE_KEY, JSON.stringify({
      savedAt: Date.now(),
      rows
    }));
  } catch (err) {
    localStorage.removeItem(PUBLIC_CACHE_KEY);
  }
}

function getPublicResearchCacheKey(personId) {
  return `${PUBLIC_RESEARCH_CACHE_PREFIX}${String(personId || '').trim()}`;
}

function renderCachedPublicResearch(personId) {
  try {
    const cached = JSON.parse(localStorage.getItem(getPublicResearchCacheKey(personId)) || 'null');
    if (!cached || Date.now() - cached.savedAt > PUBLIC_CACHE_MAX_AGE) return false;
    setPublicResearch(cached.rows || []);
    return true;
  } catch (err) {
    localStorage.removeItem(getPublicResearchCacheKey(personId));
    return false;
  }
}

function cachePublicResearch(personId, rows) {
  try {
    localStorage.setItem(getPublicResearchCacheKey(personId), JSON.stringify({
      savedAt: Date.now(),
      rows
    }));
  } catch (err) {
    localStorage.removeItem(getPublicResearchCacheKey(personId));
  }
}

// โหลดข้อมูล profile รายคนและงานวิจัยรายคน เพื่อไม่โหลดทุกอย่างตั้งแต่เปิดหน้า
async function loadPublicResearchForPerson(personId) {
  if (!personId) return [];
  if (renderCachedPublicResearch(personId)) return getResearchByPerson(personId);

  const result = await apiGet('publicResearch', { personId });
  if (!result.success) throw new Error(result.message || 'โหลดข้อมูลงานวิจัยไม่สำเร็จ');

  setPublicResearch(result.data || []);
  cachePublicResearch(personId, result.data || []);
  return getResearchByPerson(personId);
}

async function loadPublicFacultyPracticeForPerson(personId) {
  if (!personId) return [];
  const result = await apiGet('publicFacultyPractice', { personId });
  if (!result.success) throw new Error(result.message || 'โหลดข้อมูลความเชี่ยวชาญไม่สำเร็จ');

  setPublicFacultyPractice(result.data || []);
  return getFacultyPracticeByPerson(personId);
}

async function loadPublicProfile(personId) {
  const fallback = publicPeople.find(item => String(item.PERSON_ID) === String(personId));
  try {
    const result = await apiGet('publicProfile', { personId });
    if (result.success && result.data) return result.data;
  } catch (err) {
    return fallback;
  }
  return fallback;
}

function setPublicDirectoryBusy(message) {
  const summary = document.getElementById('resultSummary');
  const cards = document.getElementById('publicCards');
  if (summary) {
    summary.textContent = message || 'กำลังดำเนินการ...';
    summary.classList.add('is-busy');
  }
  if (cards) cards.classList.add('is-updating');
}

function clearPublicDirectoryBusy() {
  document.getElementById('resultSummary')?.classList.remove('is-busy');
  document.getElementById('publicCards')?.classList.remove('is-updating');
}

function renderPublicDirectory() {
  setPublicDirectoryBusy('กำลังกรองข้อมูล...');
  clearTimeout(publicRenderTimer);
  publicRenderTimer = setTimeout(renderPublicDirectoryNow, 90);
}

// Render รายชื่อหลังกรอง: ปุ่มกลุ่มหลักควบคุม group, dropdown กลุ่มวิชาไม่กระทบคณะผู้บริหาร
function renderPublicDirectoryNow() {
  const group = getActivePublicGroup() || 'EXECUTIVE';
  const department = group === 'EXECUTIVE' ? '' : document.getElementById('publicDepartment').value;
  const q = normalizeText(document.getElementById('publicSearch').value).toLowerCase();

  const rows = publicPeople.filter(person => {
    const haystack = [
      person.FULL_NAME,
      person.POSITION,
      person.DEPARTMENT,
      person.DEPARTMENT_NAME,
      person.DEPARTMENT_ID,
      person.WORK_GROUP,
      person.WORK_GROUP,
      person.ACADEMIC_POSITION,
      person.EMAIL
    ].map(normalizeText).join(' ').toLowerCase();

    return (!group || (group === 'EXECUTIVE' ? isAcademicExecutivePerson(person) : getPersonnelGroup(person) === group))
      && (!department || [person.DEPARTMENT, person.DEPARTMENT_NAME, person.DEPARTMENT_ID]
        .some(value => normalizeDepartment(value) === normalizeDepartment(department)))
      && (!q || haystack.includes(q));
  }).sort((a, b) => group === 'EXECUTIVE' ? compareExecutivePeople(a, b) : comparePublicPeople(a, b));

  visiblePublicPeople = rows;

  document.getElementById('resultSummary').textContent =
    `แสดง ${rows.length} คน จาก ${publicPeople.length} คน`;

  const cardHtml = renderGroupedPublicCards(rows, group, department);
  document.getElementById('publicCards').innerHTML =
    cardHtml || '<div class="loading-card">ไม่พบข้อมูลตามเงื่อนไข</div>';

  updateGroupChooser(group);
  clearPublicDirectoryBusy();
}

function setPublicGroup(group) {
  updateGroupChooser(group);
  renderPublicDirectory();
}

function getActivePublicGroup() {
  return document.querySelector('.group-choice.active')?.dataset.group || '';
}

function renderPublicGroupCounts() {
  const executive = publicPeople.filter(isAcademicExecutivePerson).length;
  const academic = publicPeople.filter(person => !isAcademicExecutivePerson(person) && getPersonnelGroup(person) === 'LECTURER').length;
  const support = publicPeople.filter(person => !isExecutivePerson(person) && getPersonnelGroup(person) === 'STAFF').length;

  setText('executiveGroupCount', executive);
  setText('academicGroupCount', academic);
  setText('supportGroupCount', support);
}

function updateGroupChooser(group) {
  document.querySelectorAll('.group-choice').forEach(button => {
    button.classList.toggle('active', button.dataset.group === group);
  });
}

function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.textContent = value;
}

// แบ่งหัวข้อและ layout ของ card แต่ละกลุ่ม
// คณะผู้บริหารมี layout พิเศษ: คณบดีอยู่กลาง, แถวถัดไป 3 คน, ที่เหลือไหลตาม grid
function renderGroupedPublicCards(rows, group, department) {
  const academicTitle = group === 'LECTURER' && department
    ? getSelectedDepartmentLabel()
    : 'บุคลากรสายวิชาการ';
  const groups = group === 'EXECUTIVE'
    ? [['คณะผู้บริหาร', rows, 'executive-group']]
    : group === 'LECTURER'
    ? [[academicTitle, rows, 'academic-group']]
    : group === 'STAFF'
    ? [
        ['ผู้บริหารสายสนับสนุน', rows.filter(isSupportExecutivePerson), 'support-executive-group'],
        ['บุคลากรสายสนับสนุน', rows.filter(person => !isSupportExecutivePerson(person)), 'support-group']
      ]
    : [
        ['คณะผู้บริหาร', rows.filter(isAcademicExecutivePerson), 'executive-group'],
        ['บุคลากรสายวิชาการ', rows.filter(person => !isAcademicExecutivePerson(person) && getPersonnelGroup(person) === 'LECTURER'), 'academic-group'],
        ['บุคลากรสายสนับสนุน', rows.filter(person => !isExecutivePerson(person) && getPersonnelGroup(person) === 'STAFF'), 'support-group']
      ];

  return groups
    .filter(item => item[1].length)
    .map(item => `
      <div class="group-heading ${escapeAttr(item[2] || '')}">${escapeHtml(item[0])}</div>
      ${item[2] === 'executive-group' ? renderExecutiveCards(item[1]) : item[1].map(person => renderPersonCard(person, item[2])).join('')}
    `)
    .join('');
}

// Layout เฉพาะกลุ่มคณะผู้บริหาร
function renderExecutiveCards(rows) {
  const dean = rows.find(isDeanPerson);
  const others = rows.filter(person => !isDeanPerson(person));
  const secondRow = others.slice(0, 3);
  const rest = others.slice(3);

  return `
    <div class="executive-layout">
      ${dean ? `<div class="executive-dean-row">${renderPersonCard(dean, 'executive-group')}</div>` : ''}
      ${secondRow.length ? `<div class="executive-second-row">${secondRow.map(person => renderPersonCard(person, 'executive-group')).join('')}</div>` : ''}
      ${rest.length ? `<div class="executive-rest-row">${rest.map(person => renderPersonCard(person, 'executive-group')).join('')}</div>` : ''}
    </div>
  `;
}

// สร้าง HTML ของ card บุคลากร 1 คน
function renderPersonCard(person, groupClass) {
  const id = escapeAttr(person.PERSON_ID);
  const photo = person.PIC || 'https://cdn-icons-png.flaticon.com/512/149/149071.png';
  const workGroup = getPersonnelGroup(person) === 'LECTURER' ? 'สายวิชาการ' : 'สายสนับสนุน';
  const executiveLabel = getExecutiveLabel(person);
  const executiveTag = executiveLabel ? `<span class="tag">${escapeHtml(executiveLabel)}</span>` : '';
  const departmentText = getPersonDepartmentText(person);
  const cardClass = [
    'person-card',
    groupClass || '',
    isDeanPerson(person) ? 'is-dean' : '',
    isSupportExecutivePerson(person) ? 'is-support-executive' : '',
    isExecutivePerson(person) ? 'is-executive' : ''
  ].filter(Boolean).join(' ');

  return `
    <article class="${cardClass}" data-person-id="${id}" onclick="showPublicProfile('${id}')">
      <div class="person-top">
        <img class="person-photo" src="${escapeAttr(photo)}" alt="" loading="lazy" decoding="async">
        <div class="person-content">
          <h3 class="person-name">${escapeHtml(getPublicDisplayName(person))}</h3>
          <p class="person-role">${escapeHtml(person.POSITION || person.ACADEMIC_POSITION || '-')}</p>
          <div class="person-meta">
            <span>${escapeHtml(departmentText || '-')}</span>
            <span>${escapeHtml(person.EMAIL || '')}</span>
          </div>
          <div class="tag-row">
            <span class="tag">${escapeHtml(workGroup)}</span>
            <span class="tag">${escapeHtml(person.WORK_GROUP || '-')}</span>
            ${executiveTag}
          </div>
        </div>
      </div>
    </article>
  `;
}

// เปิดหน้ารายละเอียดบุคลากร โดยโหลด profile/research เพิ่มเฉพาะคนที่เลือก
async function showPublicProfile(personId) {
  setPublicDirectoryBusy('กำลังเปิดรายละเอียด...');
  const person = await loadPublicProfile(personId);
  if (!person) {
    clearPublicDirectoryBusy();
    return;
  }

  const isTeacher = getPersonnelGroup(person) === 'LECTURER';
  const photo = person.PIC || 'https://cdn-icons-png.flaticon.com/512/149/149071.png';
  const profile = document.getElementById('publicProfile');
  let researchRows = [];
  let practiceRows = [];
  try {
    researchRows = await loadPublicResearchForPerson(personId);
  } catch (err) {
    researchRows = [];
  }
  try {
    practiceRows = await loadPublicFacultyPracticeForPerson(personId);
  } catch (err) {
    practiceRows = [];
  }
  const researchBlocks = researchRows.map(renderResearch).join('');
  const practiceBlocks = practiceRows.map(renderFacultyPractice).join('');

  const educationBlocks = [
    renderEducation('ปริญญาตรี', person.BACHELOR_DEGREE, person.BACHELOR_MAJOR, person.BACHELOR_DEGREES_INST_ID, person.BACHELOR_DEGREES_YEAR),
    renderEducation('ปริญญาโท', person.MASTER_DEGREE, person.MASTER_MAJOR, person.MASTER_DEGREES_INST_ID, person.MASTER_DEGREES_YEAR),
    renderEducation('ปริญญาเอก', person.DOCTORAL_DEGREE, person.DOCTORAL_MAJOR, person.DOCTORAL_DEGREES_OTHER_ID, person.DOCTORAL_DEGREES_YEAR)
  ].filter(Boolean).join('');

  profile.innerHTML = `
    <div class="profile-page-head">
      <button type="button" class="back-button" onclick="closePublicProfile()">กลับไปรายชื่อ</button>
      <div>
        <span>รายละเอียดบุคลากร</span>
        <h2>${escapeHtml(getPublicDisplayName(person))}</h2>
      </div>
    </div>

    <div class="profile-modal">
      <div class="profile-content">
        <div class="profile-banner">
          <img src="${escapeAttr(photo)}" alt="" loading="eager" decoding="async">
          <div>
            <h2>${escapeHtml(getPublicDisplayName(person))}</h2>
            <p>${escapeHtml(person.POSITION || '-')}</p>
            <p>${escapeHtml(getPersonDepartmentText(person) || '-')}</p>
            <div class="tag-row">
              <span class="tag">${escapeHtml(getPersonnelGroup(person) === 'LECTURER' ? 'สายวิชาการ' : 'สายสนับสนุน')}</span>
              ${getExecutiveLabel(person) ? `<span class="tag">${escapeHtml(getExecutiveLabel(person))}</span>` : ''}
              ${person.ACADEMIC_POSITION ? `<span class="tag">${escapeHtml(person.ACADEMIC_POSITION)}</span>` : ''}
            </div>
          </div>
        </div>

        <div class="profile-body">
          <aside class="profile-section-tabs">
            <button type="button" class="side-tab active" onclick="scrollProfileSection('contactSection')">ข้อมูลติดต่อ</button>
            <button type="button" class="side-tab" onclick="scrollProfileSection('educationSection')">ข้อมูลการศึกษา</button>
            ${isTeacher ? `<button type="button" class="side-tab" onclick="scrollProfileSection('experienceSection')">ประสบการณ์</button>` : ''}
            ${researchBlocks ? `<button type="button" class="side-tab" onclick="scrollProfileSection('researchSection')">งานวิจัย</button>` : ''}
          </aside>

          <div class="profile-scroll">
          <section class="profile-section" id="contactSection">
            <details class="profile-section-toggle" open>
              <summary>ข้อมูลติดต่อและหน่วยงาน</summary>
              <div class="info-grid">
                ${renderInfo('อีเมล', person.EMAIL)}
                ${renderInfo('หน่วยงานภายใน', getPersonDepartmentText(person))}
                ${renderInfo('ตำแหน่ง', person.POSITION)}
              </div>
            </details>
          </section>

        ${educationBlocks ? `
          <section class="profile-section" id="educationSection">
            <details class="profile-section-toggle" open>
              <summary>ข้อมูลการศึกษา</summary>
              <p class="section-kicker">ประวัติการศึกษา</p>
              <div class="education-list">${educationBlocks}</div>
            </details>
          </section>
        ` : ''}

        ${isTeacher ? `
          <section class="profile-section" id="experienceSection">
            <details class="profile-section-toggle" open>
              <summary>ประสบการณ์และความเชี่ยวชาญ</summary>
              <div class="experience-list">
                ${renderExperience('ประสบการณ์พยาบาล', firstValue(person.EXPERIENCE_NURSE, person.EXPERENCE_NURSE))}
                ${renderExperience('ประสบการณ์สอน', firstValue(person.EXPERIENCE_TEACH, person.EXPERENCE_TEACH))}
                ${renderExperience('ความเชี่ยวชาญ', firstValue(person.PROFICIENCY, person.EXPERTISE))}
                ${practiceBlocks}
              </div>
            </details>
          </section>
        ` : ''}

        ${researchBlocks ? `
          <section class="profile-section" id="researchSection">
            <details class="profile-section-toggle">
              <summary>
                <span>ผลงานวิจัย / วิชาการ</span>
                <b>${researchRows.length} รายการ</b>
              </summary>
              <div class="research-list">${researchBlocks}</div>
            </details>
          </section>
        ` : ''}
          </div>
        </div>
      </div>
    </div>
  `;

  document.getElementById('directoryPanel').classList.add('hidden');
  profile.classList.remove('hidden');
  clearPublicDirectoryBusy();
  profile.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function getResearchByPerson(personId) {
  return publicResearch
    .filter(item => String(item.PERSON_ID || '').trim() === String(personId || '').trim())
    .sort((a, b) => {
      const yearA = parseInt(a['YEAR ค.ศ'] || a.YEAR || a['ปี พ.ศ.'], 10) || 0;
      const yearB = parseInt(b['YEAR ค.ศ'] || b.YEAR || b['ปี พ.ศ.'], 10) || 0;
      return yearB - yearA;
    });
}

function getFacultyPracticeByPerson(personId) {
  return publicFacultyPractice
    .filter(item => String(item.PERSON_ID || '').trim() === String(personId || '').trim())
    .sort((a, b) => (parseInt(b.FISCAL_YEAR_BE, 10) || 0) - (parseInt(a.FISCAL_YEAR_BE, 10) || 0));
}

function renderFacultyPractice(item) {
  const title = firstValue(item.EXPERTISE, item.CARE_TYPE, item.CARE_SUBTYPES);
  const detail = [
    item.CARE_SUBTYPES,
    item.ACADEMIC_GROUP,
    item.OPERATION_STATUS,
    item.FISCAL_YEAR_BE ? `ปีงบประมาณ ${item.FISCAL_YEAR_BE}` : '',
    item.SUMMARY_RESULT
  ].filter(Boolean).join(' | ');

  return renderExperience(title || 'ความเชี่ยวชาญ/บริการวิชาการ', detail || title);
}

function renderResearch(item) {
  const link = String(item.LINK || '').trim();
  const title = firstResearchValue(item, ['TITLE', 'ชื่อเรื่อง']) || '-';
  const year = firstResearchValue(item, ['YEAR ค.ศ', 'YEAR', 'ปี พ.ศ.']);
  const meta = [
    firstResearchValue(item, ['JOURNAL']),
    year,
    firstResearchValue(item, ['ตีพิมพ์', 'สถานะ']),
    firstResearchValue(item, ['TYPE']),
    firstResearchValue(item, ['INDEX_STATUS']),
    firstResearchValue(item, ['Level'])
  ].filter(Boolean).join(' | ');
  const fund = [
    firstResearchValue(item, ['ทุน']),
    firstResearchValue(item, ['แหล่งทุน']),
    formatResearchMoney(firstResearchValue(item, ['จำนวนเงิน']))
  ].filter(Boolean).join(' | ');
  const note = [
    firstResearchValue(item, ['สาขาวิชา']),
    firstResearchValue(item, ['ref'])
  ].filter(Boolean).join(' | ');

  return `
    <article class="research-entry">
      <div class="research-icon">R</div>
      <div class="research-card">
        <div>
          <span class="research-pill">${escapeHtml(year || 'ผลงานวิจัย')}</span>
          <div class="research-heading">${escapeHtml(title)}</div>
        </div>
        ${meta ? `<div class="research-meta">${escapeHtml(meta)}</div>` : ''}
        ${fund ? `<div class="research-fund">${escapeHtml(fund)}</div>` : ''}
        ${note ? `<div class="research-meta">${escapeHtml(note)}</div>` : ''}
        ${link ? `<a class="research-link" href="${escapeAttr(link)}" target="_blank" rel="noopener">เปิดผลงาน</a>` : ''}
      </div>
    </article>
  `;
}

function firstResearchValue(item, keys) {
  for (const key of keys) {
    const value = item && item[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}

function formatResearchMoney(value) {
  if (value === undefined || value === null || String(value).trim() === '') return '';
  const number = Number(String(value).replace(/,/g, ''));
  if (!isNaN(number)) return `${number.toLocaleString('th-TH')} บาท`;
  return value;
}

function closePublicProfile() {
  document.getElementById('publicProfile').classList.add('hidden');
  document.getElementById('directoryPanel').classList.remove('hidden');
  document.querySelector('.public-main').scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function scrollProfileSection(sectionId) {
  const section = document.getElementById(sectionId);
  if (section) section.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function renderEducation(label, degree, major, institute, year) {
  if (!degree && !major && !institute && !year) return '';
  return `
    <article class="education-entry">
      <div class="education-icon">🎓</div>
      <div class="education-card">
        <div class="degree-pill">${escapeHtml(label)}${degree ? ` : ${escapeHtml(degree)}` : ''}</div>
        ${major ? `<div class="education-line">สาขา ${escapeHtml(major)}</div>` : ''}
        ${institute ? `<div class="education-line">${escapeHtml(institute)}</div>` : ''}
        ${year ? `<div class="education-year">สำเร็จการศึกษา ${escapeHtml(year)}</div>` : ''}
      </div>
    </article>
  `;
}

function renderExperience(label, value) {
  if (!value) return '';
  return `
    <article class="experience-entry">
      <div class="experience-icon">★</div>
      <div class="experience-card">
        <div class="experience-pill">${escapeHtml(label)}</div>
        <div class="experience-text">${escapeHtml(value)}</div>
      </div>
    </article>
  `;
}

function firstValue() {
  for (let i = 0; i < arguments.length; i += 1) {
    const value = arguments[i];
    if (value == null) continue;
    const text = String(value).trim();
    if (text && text !== '-') return text;
  }
  return '';
}

function getPublicDisplayName(person) {
  const fullName = normalizeText(person && person.FULL_NAME);
  if (!fullName) return '-';
  if (getPersonnelGroup(person) !== 'LECTURER') return fullName;

  const academicPrefix = getAcademicTitlePrefix(person);
  const doctoralPrefix = hasDoctoralDegree(person) ? 'ดร.' : '';
  const prefixes = [academicPrefix, doctoralPrefix].filter(Boolean);
  if (!prefixes.length) return fullName;

  const cleanName = stripDisplayNamePrefixes(fullName);
  return `${prefixes.join(' ')} ${cleanName}`.replace(/\s+/g, ' ').trim();
}

function getAcademicTitlePrefix(person) {
  const position = normalizeText(person && person.ACADEMIC_POSITION);

  if (!position) return '';
  if (position === 'ศ.' || position === 'ศาสตราจารย์') return 'ศ.';
  if (position === 'รศ.' || position === 'รองศาสตราจารย์') return 'รศ.';
  if (position === 'ผศ.' || position === 'ผู้ช่วยศาสตราจารย์') return 'ผศ.';
  if (position === 'อาจารย์' || position === 'LECTURER') return 'อาจารย์';
  return '';
}

function hasDoctoralDegree(person) {
  if (isTrueValue(person && person.HAS_DOCTORAL_DEGREE)) return true;
  const rows = Array.isArray(person && person.EDUCATION_ROWS) ? person.EDUCATION_ROWS : [];

  return rows.some(row => normalizeText(row && row.DEGREE_LEVEL).toUpperCase() === 'DOCTORAL');
}

function stripDisplayNamePrefixes(name) {
  return normalizeText(name)
    .replace(/^(ศ\.|รศ\.|ผศ\.|อาจารย์|ดร\.|อ\.|ศาสตราจารย์|รองศาสตราจารย์|ผู้ช่วยศาสตราจารย์)\s*/g, '')
    .replace(/^(ศ\.|รศ\.|ผศ\.|อาจารย์|ดร\.|อ\.)\s*/g, '')
    .trim();
}

function renderInfo(label, value) {
  if (!value) return '';
  return `
    <div class="info-item">
      <span class="info-label">${escapeHtml(label)}</span>
      <div class="info-value">${escapeHtml(value)}</div>
    </div>
  `;
}

function isPublicPerson(person) {
  if (!isPersonnelRecord(person)) return false;
  if (String(person.ACTIVE_SYS).trim().toLowerCase() !== 'true') return false;
  if (normalizeText(person.WORK_STATUS || 'ปฏิบัติงาน') !== 'ปฏิบัติงาน') return false;
  return true;
}

function isPersonnelRecord(person) {
  const type = normalizeText(person && person.WORK_GROUP).toLowerCase();
  const role = normalizeText(person && person.ROLE).toLowerCase();
  const userType = normalizeText(person && person.USER_TYPE).toLowerCase();
  const position = normalizeText(person && person.POSITION).toLowerCase();
  const name = normalizeText(person && person.FULL_NAME).toLowerCase();
  const blocked = ['bot', 'admin', 'admin ระบบ', 'ผู้ดูแลระบบ', 'แอดมินระบบ'];

  return !blocked.some(keyword =>
    type === keyword ||
    role === keyword ||
    userType === keyword ||
    position === keyword ||
    name === keyword
  );
}

function normalizeText(value) {
  return String(value || '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeDepartment(value) {
  return normalizeText(value)
    .replace(/ฯ/g, '')
    .replace(/^กลุ่มวิชา/g, '')
    .replace(/^สาขาวิชา/g, '')
    .replace(/^สาขา/g, '')
    .replace(/\s+/g, '');
}

function toDepartmentFilterLabel(value) {
  const text = normalizeText(value);
  if (!text) return '';
  if (text.indexOf('สาขาวิชา') === 0) return text.replace(/^สาขาวิชา/, 'กลุ่มวิชา');
  if (text.indexOf('สาขา') === 0) return text.replace(/^สาขา/, 'กลุ่มวิชา');
  return text;
}

function displayDepartment(value) {
  return toDepartmentFilterLabel(value);
}

function getSelectedDepartmentLabel() {
  const select = document.getElementById('publicDepartment');
  const option = select?.selectedOptions?.[0];
  return displayDepartment(option?.dataset?.departmentName || option?.textContent || option?.value || '');
}

function getPersonDepartmentText(person) {
  return displayDepartment(firstValue(
    person && person.DEPARTMENT_NAME,
    person && person.DEPARTMENT,
    person && person.DEPARTMENT_ID,
    person && person.ACADEMIC_GROUP,
    person && person.SUBJECT_GROUP,
    person && person.WORK_GROUP
  ));
}

function isDeanPosition(position) {
  return position === 'คณบดีคณะพยาบาลศาสตร์' || position === 'คณบดี';
}

function isHeadOfficePosition(position) {
  return position.indexOf('หัวหน้าสำนัก') === 0;
}

function getPersonnelGroup(person) {
  const type = normalizeText(person && person.WORK_GROUP);
  const workGroup = normalizeText(person && person.WORK_GROUP);
  const position = normalizeText(person && person.POSITION);

  if (workGroup.indexOf('วิชาการ') >= 0) return 'LECTURER';
  if (workGroup.indexOf('สนับสนุน') >= 0) return 'STAFF';

  if (
    type === 'เจ้าหน้าที่' ||
    position === 'เจ้าหน้าที่' ||
    isHeadOfficePosition(position)
  ) {
    return 'STAFF';
  }

  if (
    type === 'อาจารย์' ||
    position === 'อาจารย์' ||
    isDeanPosition(position) ||
    position.indexOf('รองคณบดี') === 0 ||
    position === 'ผู้ช่วยคณบดี'
  ) {
    return 'LECTURER';
  }

  return type || position || '';
}

function isExecutivePerson(person) {
  return isTrueValue(person && person.IS_EXECUTIVE);
}

function isAcademicExecutivePerson(person) {
  return isExecutivePerson(person) && getPersonnelGroup(person) === 'LECTURER';
}

function isDeanPerson(person) {
  return isDeanPosition(normalizeText(person && person.POSITION)) || getExplicitOrder(person) === 1;
}

function isSupportExecutivePerson(person) {
  return isExecutivePerson(person) && getPersonnelGroup(person) === 'STAFF';
}

function getExecutiveLabel(person) {
  if (!isExecutivePerson(person)) return '';
  return isSupportExecutivePerson(person) ? 'ผู้บริหารสายสนับสนุน' : 'คณะผู้บริหาร';
}

function comparePublicPeople(a, b) {
  const execCompare = compareExecutivePeople(a, b);
  if (execCompare !== 0) return execCompare;

  const groupCompare = getGroupRank(a) - getGroupRank(b);
  if (groupCompare !== 0) return groupCompare;

  const dep = normalizeText(a.DEPARTMENT).localeCompare(normalizeText(b.DEPARTMENT), 'th');
  if (dep !== 0) return dep;

  return normalizeText(a.FULL_NAME).localeCompare(normalizeText(b.FULL_NAME), 'th');
}

function compareExecutivePeople(a, b) {
  const rank = getExecutiveRank(a) - getExecutiveRank(b);
  if (rank !== 0) return rank;
  return normalizeText(a.FULL_NAME).localeCompare(normalizeText(b.FULL_NAME), 'th');
}

function getGroupRank(person) {
  if (isExecutivePerson(person)) return 1;
  return getPersonnelGroup(person) === 'LECTURER' ? 2 : 3;
}

function getExecutiveRank(person) {
  const position = normalizeText(person && person.POSITION);
  if (isDeanPosition(position)) return 1;
  if (position.indexOf('รองคณบดีฝ่ายบริหาร') === 0) return 2;
  if (position.indexOf('รองคณบดีฝ่ายวิชาการ') === 0) return 3;
  if (position.indexOf('รองคณบดีฝ่ายกิจการ') === 0) return 4;
  if (position.indexOf('รองคณบดี') === 0) return 4;
  if (position === 'ผู้ช่วยคณบดี') return 5;
  if (isHeadOfficePosition(position)) return 6;

  const explicitOrder = getExplicitOrder(person);
  if (explicitOrder < 999) return explicitOrder;
  return isExecutivePerson(person) ? 50 : 999;
}

function getExplicitOrder(person) {
  const raw = person && (
    person.EXECUTIVE_ORDER ||
    person.DISPLAY_ORDER ||
    person.ORDER ||
    person.SORT_ORDER
  );
  const order = parseInt(raw, 10);
  return isNaN(order) ? 999 : order;
}

function isTrueValue(value) {
  if (value === true) return true;
  const text = normalizeText(value).toUpperCase();
  return ['TRUE', 'YES', 'Y', '1', 'ใช่'].indexOf(text) !== -1;
}

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
}

function escapeAttr(value) {
  return escapeHtml(value).replaceAll('`', '');
}
